def parse_duration(text: str) -> int:
    """
    Разбирает строку вида '1h30m', '90s', '2h', '45m', '1h2m3s' и возвращает количество секунд (int).

    :param text: Строка с длительностью
    :return: Количество секунд
    :raises ValueError: Если строка пустая или не соответствует формату
    """
    if not text:
        raise ValueError("Пустая строка")

    seconds = 0
    i = 0
    while i < len(text):
        if not text[i].isdigit():
            raise ValueError("Некорректный формат строки")
        j = i
        while j < len(text) and text[j].isdigit():
            j += 1
        if j == len(text) or text[j] not in 'hms':
            raise ValueError("Некорректный формат строки")
        num = int(text[i:j])
        if text[j] == 'h':
            seconds += num * 3600
        elif text[j] == 'm':
            seconds += num * 60
        elif text[j] == 's':
            seconds += num
        i = j + 1

    return seconds
